    ["<Assistant_Title1>【Ancient Castle Nightfall】</>\n<Assistant_Title2>Description: </>God-favored Showcase\n<Assistant_Title2>Usage: </>After use, you will obtain the Ancient Castle Nightfall. You can click <Assistant_System>Appearance - Showcase</> to view and use it. \n<Assistant_Title2>Acquisition: </>Exchange using Spirit Illusion Cards in the <Assistant_System>Summon - Spirit World Transformation - Spirit Illusion Altar Shop</>"] = "\\u003cAssistant_Title1\\u003e【Ночь в древнем замке】\\u003c/Assistant_Title1\\u003e\n\\u003cAssistant_Title2\\u003eОписание: \\u003c/Assistant_Title2\\u003eОсобый подиум Божьей милости\n\\u003cAssistant_Title2\\u003eИспользование: \\u003c/Assistant_Title2\\u003eПри использовании открывает подиум «Ночь в древнем замке». Осмотреть и применить можно в разделе \\u003cAssistant_System\\u003eВнешний вид — Подиум\\u003c/Assistant_System\\u003e.\n\\u003cAssistant_Title2\\u003eПолучение: \\u003c/Assistant_Title2\\u003eОбменивается на карты Призрачного духа в разделе \\u003cAssistant_System\\u003eПризыв — Преображение мира духов — Лавка Алтаря призраков\\u003c/Assistant_System\\u003e",
    ["Dad, why do we come to watch others eat every day?"] = "Папа, почему мы каждый день приходим посмотреть, как другие едят?",
    ["Her dream is a wasteland..."] = "Ее мечта - пустырь...",
    ["<Assistant_Title1>【Hidden Scholar】</>\n<Assistant_Title2>Description: </>Connection gameplay reward outfit\n<Assistant_Title2>Use: </>Use to obtain the Hidden Scholar set. You can view and equip it by clicking <Assistant_System>Appearance - Dress Up</>.\n<Assistant_Title2>Acquisition: </>Obtained via <Assistant_System>Mall - General Goods - Past Exhibition Hall</>, redeem using Memory Treasure Boxes"] = "\\u003cAssistant_Title1\\u003e【Ученый сокровенного】\\u003c/Assistant_Title1\\u003e\n\\u003cAssistant_Title2\\u003eОписание: \\u003c/Assistant_Title2\\u003eОблик в награду за развитие связей\n\\u003cAssistant_Title2\\u003eИспользование: \\u003c/Assistant_Title2\\u003eПри использовании разблокирует костюм «Ученый сокровенного». Осмотреть и применить можно в меню \\u003cAssistant_System\\u003eВнешний вид — Гардероб\\u003c/Assistant_System\\u003e.\n\\u003cAssistant_Title2\\u003eПолучение: \\u003c/Assistant_Title2\\u003eОбменивается на ларцы памяти в разделе \\u003cAssistant_System\\u003eМагазин — Универмаг — Зал воспоминаний\\u003c/Assistant_System\\u003e",
